const servers: HalServer[] = [];
const clients: WebSocket[] = [];

/** Waits briefly for an asynchronous socket event without leaving teardown races behind. */
export async function eventually(check: () => boolean): Promise<void> {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
}

/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
export const answeringOrchestrator: ChatOrchestrator = {
  processMessage: async () => 'hi',
  async *processMessageStream(): AsyncGenerator<MessageChunk> {
    yield {type: 'text', text: 'hi'};
    yield {type: 'stop', stopReason: 'end_turn'};
  },
};

/** Starts an engine on an ephemeral port and returns the URL a client should open. */
export async function startEngine(
  sessionStore: SessionStore,
  onDisconnect?: (sessionId: string) => void
): Promise<string> {
  const {url} = await startEngineWith({sessionStore, onDisconnect});
  return url;
}

/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
export async function startEngineWith(
  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
): Promise<{url: string; hal: HalServer}> {
  const hal = createServer({
    app: (() => undefined) as unknown as Express,
    wsAuth: async () => ({id: 'u1'}),
    orchestrator: answeringOrchestrator,
    ...options,
  });
  await hal.start(0);
  servers.push(hal);
  const {port} = hal.server.address() as AddressInfo;
  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
}

/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
export function connectClient(url: string, token = 't'): WebSocket {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
  clients.push(client);
  return client;
}

/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
export function deferred(): {until: Promise<void>; release: () => void} {
  let release = (): void => undefined;
  const until = new Promise<void>(resolve => {
    release = resolve;
  });
  return {until, release};
}

/** Resolves with every frame type seen up to and including the first `until` frame. */
export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
  const seen: string[] = [];
  return new Promise<string[]>(resolve => {
    client.on('message', raw => {
      const {type} = JSON.parse(String(raw)) as {type: string};
      seen.push(type);
      if (type === until) resolve(seen);
    });
  });
}

/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
export function askOnOpen(
  url: string,
  {until = 'stream_end', token}: {until?: string; token?: string} = {}
): {client: WebSocket; finished: Promise<string[]>} {
  const client = connectClient(url, token);
  const finished = framesUntil(client, until);

import {readFileSync} from 'node:fs';
import {join} from 'node:path';
import {HAL_WS_SUBPROTOCOL, credentialFromSubprotocol, selectSubprotocol} from './subprotocol.js';

const TOKEN = 'super-secret-token';

const doc = (path: string): string => readFileSync(join(process.cwd(), path), 'utf8');

describe('the hal.v1 marker', () => {
  it('is the literal the protocol spec and the getting-started client print', () => {
    const printed = {
      spec: doc('specs/hal-engine-websocket-protocol/spec.md').includes(
        `Sec-WebSocket-Protocol: ${HAL_WS_SUBPROTOCOL}, <access-token>`
      ),
      client: doc('docs/getting-started.md').includes(`['${HAL_WS_SUBPROTOCOL}', token]`),
    };

    expect({marker: HAL_WS_SUBPROTOCOL, printed}).toEqual({marker: 'hal.v1', printed: {spec: true, client: true}});
  });
});

describe('selectSubprotocol', () => {
  it('answers the marker when it is offered first, never the token beside it', () => {
    expect(selectSubprotocol(new Set([HAL_WS_SUBPROTOCOL, TOKEN]))).toBe(HAL_WS_SUBPROTOCOL);
  });

  it('answers the marker when it is offered after the token', () => {
    expect(selectSubprotocol(new Set([TOKEN, HAL_WS_SUBPROTOCOL]))).toBe(HAL_WS_SUBPROTOCOL);
  });

  it('answers nothing for a bare token offered without the marker', () => {
    expect(selectSubprotocol(new Set([TOKEN]))).toBe(false);
  });

  it('answers nothing for an empty offer', () => {
    expect(selectSubprotocol(new Set())).toBe(false);
  });
});

describe('credentialFromSubprotocol', () => {
  it('reads the token from a marker-first offer', () => {
    expect(credentialFromSubprotocol(`${HAL_WS_SUBPROTOCOL}, ${TOKEN}`)).toBe(TOKEN);
  });

  it('reads the token from a token-first offer', () => {
    expect(credentialFromSubprotocol(`${TOKEN}, ${HAL_WS_SUBPROTOCOL}`)).toBe(TOKEN);
  });

  it('reads the first non-marker value when two are offered beside the marker', () => {
    expect(credentialFromSubprotocol(`${HAL_WS_SUBPROTOCOL}, first, second`)).toBe('first');
  });

  it('reads nothing from a bare token offered without the marker', () => {
    expect(credentialFromSubprotocol(TOKEN)).toBeUndefined();
  });

  it('reads nothing when only the marker is offered', () => {
    expect(credentialFromSubprotocol(HAL_WS_SUBPROTOCOL)).toBeUndefined();
  });

